// ---------- fact (specVersion 2) ----------

export interface FactEvent {
  /** unique within the diagram */
  id: string
  /** ISO 8601. Go to seconds when known, otherwise stop at the day. **Leave it out when the material gives no date: never make one up.** The card then says the date is unknown; the order is the order of slots, so nothing moves */
  date?: string
  /** card title; about 20 characters per line, at most two lines */
  label: string
  /** for a span, the end instant; needs date, and must not be earlier than it */
  dateEnd?: string
  /** time is not exact (estimated or inferred); the diagram shows "approx." */
  approx?: boolean
  /** why the time is not exact, and how it was derived */
  dateNote?: string
  /** the line under the card title; about 22 characters */
  summary?: string
  /** full text revealed when the card is opened */
  detail?: string
  /** parties involved. One: that party's side and column. Two or more, or none: the centre axis */
  actorIds?: string[]
  /** only when the diagram has 0 or 1 party: which side this event falls on. With 2 or more parties, leave it out */
  groupId?: string
  /** which materials it rests on */
  sourceIds?: string[]
}

export interface FactActor {
  /** unique within the diagram; events reference it via actorIds */
  id: string
  /** display name, e.g. "Huayuan Trading" */
  name: string
  /** procedural standing, e.g. "plaintiff" */
  role?: string
  /** the side this party is on: the 1st or the 2nd group. Required with 2 or more parties; not written with one */
  groupId?: string
}

export interface FactGroup {
  /** parties (2 or more) or events (one party) reference it via groupId */
  id: string
  /** column heading, e.g. "Sun Hao's side" (parties) or "performance as agreed" (one party's acts) */
  label: string
}

export interface FactSource {
  /** events reference it via sourceIds */
  id: string
  /** contract / evidence / judgment / transcript, etc. */
  type: string
  /** material name, e.g. "corridor surveillance video" */
  name: string
  /** location, e.g. { file, page } or { file, timestamp } */
  loc?: Record<string, unknown>
  /** verbatim excerpt (several passages joined with ……), shown when the card is opened; a shortened or reworded version goes in detail */
  quote?: string
}

export interface FactSlot {
  /** events at this time point; must not be empty */
  events: FactEvent[]
}

export interface FactSpec {
  type: "fact"
  /** which generation of this format the file follows (now 2); omit = the current one. Write it: it is how an older file is recognised after a breaking change */
  specVersion?: 2
  /** diagram title, shown at the top left */
  title: string
  actors?: FactActor[]
  groups?: FactGroup[]
  sources?: FactSource[]
  slots?: FactSlot[]
}

